const body = $input.item.json.body || $input.item.json;
// Slack URL verification challenge
if (body.type === 'url_verification') {
  return [{ json: { __respond: true, challenge: body.challenge } }];
}
const event = body.event || {};
// Only handle app_mention and direct message events
if (!['app_mention', 'message'].includes(event.type)) return [];
if (event.bot_id) return []; // ignore bot messages
const text = (event.text || '').replace(/<@[^>]+>/g, '').trim();
if (!text) return [];
return [{ json: { query: text, user_id: event.user, channel: event.channel, thread_ts: event.thread_ts || event.ts, tenant_id: body.team_id || 'corp-default' } }];

const searchResp = $input.item.json;
const results = searchResp.results || [];
if (!results.length) {
  return [{ json: { text: ':mag: No results found for your query. Try rephrasing or check connector sync status.', channel: $('Parse Slack Event').item.json.channel, thread_ts: $('Parse Slack Event').item.json.thread_ts } }];
}
const top = results.slice(0, 3);
const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: ':brain: *AegisMind Results* for: _' + $('Parse Slack Event').item.json.query + '_' } },
  { type: 'divider' }
];
top.forEach((r, i) => {
  const citation = r.citation || {};
  const score = (r.score * 100).toFixed(1);
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*' + (i+1) + '. ' + (citation.title || r.chunk_id || 'Document') + '* (' + score + '%)
' + (r.text || '').slice(0, 300) + (r.text?.length > 300 ? '...' : '') } });
  if (citation.url) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ':link: <' + citation.url + '|View Source>' }] });
});
return [{ json: { blocks, channel: $('Parse Slack Event').item.json.channel, thread_ts: $('Parse Slack Event').item.json.thread_ts } }];
